D=json.loads((P/'US916_Coupled_Results.json').read_text()); rows=[r for r in D['rows'] if r['scenario']=='central' and r['carbon_shadow_usd_t']==100]; a,b,c=rows[:3]
def replace(p,t):
    p.text=t;p.alignment=A.JUSTIFY
    for r in p.runs:r.font.size=Pt(12)
def insert_after(p,t,style='Normal'):
    x=OxmlElement('w:p');p._p.addnext(x);q=Paragraph(x,p._parent);q.style=style;replace(q,t);return q
summary='One-sentence summary: For identical modelled 2050 services, the transport pathway cuts partial emissions by 93.0% versus continued petroleum use and 86.0% versus AEO2026; integrated methane mitigation and biomethane routing can avoid 3.10 and 1.45 Gt CO₂e/year, respectively, with conditional annual savings of $18.0 billion against the late-2025 petroleum price case but a premium over AEO2026.'
abstract='A petroleum-free U.S. transport pathway reduces partial emissions by 93.0% versus continued petroleum and 86.0% versus AEO2026. Anaerobic digestion, methane monitoring and Asparagopsis supplementation, with biomethane routed to pipeline demand, yield combined conditional abatement of 3.10 and 1.45 Gt CO₂e/year, respectively. At $658.3 billion/year, the integrated pathway saves $18.0 billion against the late-2025 petroleum price case but costs $181.2 billion more than AEO2026. Crop residues save $6.78 billion/year versus the no-crop pathway; 59.8% of transport uncertainty draws select none. These are annual screening results; resource availability, lifecycle harmonisation, sustained mitigation and hourly feasibility remain unverified.'
comparison='A second counterfactual holds the central alternative’s nine modelled 2050 service demands fixed and supplies them with conventional petroleum fuels and pipeline fossil gas. It produces 3,292.20 Mt CO₂e/year using the inherited fuel-specific partial well-to-wheel factors. Before biomethane routing, the audited alternative emits 229.38 Mt/year (93.0% lower), while the independently reconstructed AEO2026 reference is 1,638.8 Mt/year (86.0% lower). With inherited late-2025 pretax liquid-fuel prices, continued petroleum costs $676.27 billion/year; the inherited November-2026 price case costs $1,007.70 billion/year. These are price sensitivities on the same model services, not forecasts or fully harmonised total ownership comparisons. Common conventional ownership costs are excluded; alternative net vehicle and infrastructure premia are retained.'
routing='A sequential constrained gas-routing linear programme assigns each delivered unit of biomethane either to residual transport pipeline-gas demand or external sale, never both. Central production is 28.20 TWh/year LHV; 160.46 TWh/year of residual pipeline demand is represented on the inherited HHV basis. At zero carbon shadow value, external sale is cost-minimising; at $100/t CO₂e shadow value, all central output is routed internally (31.30 TWh HHV), avoiding 5.70 Mt/year of fossil combustion CO₂ with no additional upstream credit. The shadow value is not cash revenue. The agricultural screen adds 33.41 Mt/year independently. Internal routing yields combined annual abatement of 3,101.92 Mt against continued petroleum and 1,448.52 Mt against AEO2026. Annual combined cost is $658.30 billion, or $17.98 billion less than the late-2025 price case, $349.41 billion less than the inherited higher-price case, and $181.20 billion more than AEO2026. Agricultural common costs remain excluded; no full cross-sector percentage is claimed. The transport production LP is rerun, but gas routing is sequential, not a simultaneous spatial or hourly investment optimisation (S34, Fig. S32).'
conclusion='The audited transport pathway reduces partial emissions by 93.0% against a same-service continued-petroleum counterfactual and 86.0% against the AEO2026-based partial reference. The integrated central internal-gas-routing case avoids 3.10 or 1.45 Gt CO₂e/year, respectively, with conditional annual expenditure of $658.3 billion: $18.0 billion below the late-2025 petroleum price case, $349.4 billion below the inherited higher-price case, and $181.2 billion above AEO2026. Crop integration independently saves $6.78 billion/year relative to the matched no-crop alternative. The model retains all community, agricultural and energy pathways without speculative credits. The price cases do not establish a 2050 forecast or economy-wide savings; county-level supplies, collection logistics, feed safety and efficacy, lifecycle harmonisation, hourly operation and deployment require independent validation.'
def main():
    m=Document(P/'Research_Article_V9.15_Science.docx'); p=m.paragraphs
    replace(p[4],summary);replace(p[6],abstract);replace(p[8],p[8].text.replace('A petroleum-only comparison at historical prices would therefore misstate the counterfactual (1).','We report both the AEO2026 comparison and an explicitly conditional continued-petroleum counterfactual at inherited prices (1).'));replace(p[45],conclusion)
    replace(p[79],'Data and materials availability: The V9.16 archive includes the preserved V9.14.1 model, exact central rerun and matched no-crop solve, the incremental methane model, the constrained gas-routing module, 45 comparative scenarios and validation outputs. Public repository availability must be confirmed before submission. County-level inputs, full lifecycle harmonisation and deployment remain unverified.');replace(p[80],'Supplementary materials: Text S1–S34; Tables S1–S18; Figs. S1–S32, including the Grid Harvester schematic S1 and energy chart S22. Existing corrected TIFFs are unchanged. The two additional numerical charts are 600 dpi.')
    q=insert_after(p[33],comparison);insert_after(q,routing);m.save(P/'Research_Article_V9.16_Science.docx')
    s=Document(P/'Supplementary_Materials_V9.15_Science.docx');p=s.paragraphs;replace(p[5],summary.removeprefix('One-sentence summary: '));replace(p[186],conclusion)
    q=insert_after(p[184],'S34. Continued-petroleum service matching and constrained biomethane routing','Heading 2');q=insert_after(q,comparison);q=insert_after(q,routing)
    q=insert_after(q,'The source implementation is us916_coupled.py. It reconstructs the audited 166-Mt crop case and the matched zero-crop alternative from the original AEO workbook archive, then solves a two-variable gas allocation LP. The constraint is internal + external = delivered methane; internal ≤ residual HHV demand / 1.11. The objective minimises the cost of gas routing less the shadow value of combustion CO₂ avoided. The fixed transport and agricultural production decisions are not reoptimised together. The 45-case CSV varies the three agricultural scenarios, carbon shadow values of $0/$100/$200 per tonne, and five cost/reference scenarios. The two additional petroleum liquid-price cases use 0.7× and 1.3× inherited late-2025 prices with pipeline gas price held fixed. Nutrient and heat credits are not assumed. All inputs and limits are explicit in V916_METHODS_AND_LIMITS.md.')
    q=insert_after(q,'');q.alignment=A.CENTER;q.add_run().add_picture(str(P/'_us916_embed.png'),width=Inches(6.25));q.paragraph_format.keep_with_next=True
    q=insert_after(q,'Fig. S32. Same-service continued-petroleum and AEO2026 partial-reference comparisons; conditional central internal biomethane routing at a $100/t shadow value. All reference values are model screens, not forecasts. Agricultural methane reductions are separate from the transport emissions shown.','Caption');s.save(P/'Supplementary_Materials_V9.16_Science.docx')
    cover=Document(P/'Cover_Letter_Science_V9.15.docx');p=cover.paragraphs;replace(p[3],'The 2050 U.S. transport pathway reduces partial emissions by 93.0% versus continued petroleum and 86.0% versus the AEO2026 reference. The additional manure, food/plant-waste, wastewater and cattle-feed programme, with constrained biomethane routing, yields indicative combined abatement of 3.10 or 1.45 Gt CO₂e/year, respectively. Integrated annual expenditure is $658.3 billion, $18.0 billion below the inherited late-2025 petroleum price case and $349.4 billion below the higher-price case, but $181.2 billion above AEO2026. These are conditional price and engineering screens, not 2050 cost forecasts.');replace(p[4],'The reproducible model retains the Grid Harvester, electricity, hydrogen, renewable fuels, nutrient and soil-carbon constraints, and adds an auditable methane-recovery and Asparagopsis screen with 1,000 diagnostic draws, an exact central transport rerun and 45 comparative gas-routing/reference cases. The findings require independent resource, lifecycle and deployment validation.');cover.save(P/'Cover_Letter_Science_V9.16.docx')
    title=Document(P/'Title_Page_V9.15_Science.docx');title.save(P/'Title_Page_V9.16_Science.docx')
if __name__=='__main__':main()
